using System.Collections.Generic;
using System.Text.Json.Serialization;

namespace Adyen.Models;

public record DonationCampaignNonprofitCause
{
    /// <summary>
    /// The URL to the banner showing the cause that the nonprofit organization supports.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("bannerUrl")]
    public string? BannerUrl { get; init; }

    /// <summary>
    /// The unique identifier of the nonprofit cause. This value is generated by Adyen.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("causeId")]
    public string? CauseId { get; init; }

    /// <summary>
    /// The description of the cause that the nonprofit supports.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("description")]
    public string? Description { get; init; }

    /// <summary>
    /// The URL to the website of the nonprofit organization.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("globalWebsiteUrl")]
    public string? GlobalWebsiteUrl { get; init; }

    /// <summary>
    /// The United Nations Sustainable Development Goals (UN SDGs) supported by the nonprofit organization, specified in the format <c>unsdg_&lt;number&gt;</c>, where the number is the number of the UN SDG. For example, <b>unsdg_1</b>.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("goals")]
    public IReadOnlyList<string>? Goals { get; init; }

    /// <summary>
    /// The URL to the logo of the nonprofit organization.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("logoUrl")]
    public string? LogoUrl { get; init; }

    /// <summary>
    /// The name of the nonprofit organization.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("nonprofitName")]
    public string? NonprofitName { get; init; }

    /// <summary>
    /// The URL to the terms and conditions of the nonprofit organization.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("termsAndConditionsUrl")]
    public string? TermsAndConditionsUrl { get; init; }
}
